// @name Kitchen sink
// @background #0b1020
// @refresh 0.05
// Most of what the JSX layer does, on one touch screen, in five pages:
// - Controls: switches, a slider you drag, a stepper (hold + for ten,
//   double-tap the number to zero it) and the accent color the UI follows.
// - Paint: tap or drag on the canvas to draw, pick a color and a brush, Undo,
//   hold Clear. A canvas (frameos.canvas): a stroke is drawn once, as lines
//   between the points the finger passes, and a frame repaints only those.
// - Lights: the Lights Out puzzle, every cell memo()'d.
// - Motion: balls bouncing on the clock, a spinner and a wave. The scene runs
//   at 0.05 s, so it animates; the other pages ask for one render a second
//   (frameos.setNextSleep), on the second, for the clock in the header.
// - Touch: every gesture and move the glass makes, where it landed, how many
//   of each, and the hover:, active: and group-hover: classes.
// Everything lives in frameos.remember, so it outlasts the interpreter, and
// every change bumps a revision: the pages are memo()'d on it, so the clock's
// render each second takes the page back whole and lays out the header alone.
// High contrast (black on white) on e-paper and where the panel shows no
// color, or when the scene's Contrast setting asks for it: the paint's inks
// greys where there is no color, solid inks (red, yellow, green, blue) where
// there is, as a color e-paper has them. On a small screen
// (a watch, a 2.8" panel, a short strip, a small round panel) the same is
// smaller, and the page scrolls.

const ACCENTS = ['sky', 'violet', 'emerald', 'rose', 'amber']
const INKS = ['#0f172a', '#ef4444', '#f59e0b', '#22c55e', '#3b82f6']
const BRUSHES = [4, 9, 16]
const TABS = [
  ['controls', 'Controls', 'M4 21v-7M4 10V3M12 21v-9M12 8V3M20 21v-5M20 12V3M1 14h6M9 8h6M17 16h6'],
  ['paint', 'Paint', 'M18.4 2.6a2 2 0 0 1 3 3L12 15l-4 1 1-4zM7 17c-2 0-3 1.5-3 3s-1 1.5-2 2c3 0 7 0 7-3a2 2 0 0 0-2-2z'],
  ['lights', 'Lights', 'M3 3h7v7H3zM14 3h7v7h-7zM14 14h7v7h-7zM3 14h7v7H3z'],
  ['motion', 'Motion', 'M22 12h-4l-3 9L9 3l-3 9H2'],
  ['touch', 'Touch', 'M12 2v4M12 18v4M2 12h4M18 12h4M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8z'],
]
const EVENT_COLORS = {
  tap: '#38bdf8', doubleTap: '#a78bfa', longPress: '#fbbf24', pointerDown: '#f8fafc', pointerUp: '#64748b',
  pointerMove: '#34d399',
}
const BALL_COLORS = ['#38bdf8', '#f472b6', '#facc15', '#4ade80', '#a78bfa', '#fb923c']
// The pages' drawing areas, in pixels: the UI less the page's padding, and
// what the header (48), the tab bar (64) and each page's own rows leave, with
// the brightness slider (less its card's padding) and the Lights board. Set by
// fit() at every render, for the handlers that run before the next; these are
// a 480x480 screen's.
let pageW = 448, sliderW = 416, boardW = 284, cellW = 52
let ctrlRow = 96 // the controls' toggles and their last row, taller on a tall page
let paintH = 276, motionH = 292, padH = 208

// High contrast on e-paper (a color one dithers the navy page and its
// translucent cards to speckle) and where the panel shows no color (black and
// white, greys), or when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && (app.frame.color === false || app.frame.paper === true))
}
const GREY_INKS = ['#000000', '#444444', '#777777', '#999999', '#bbbbbb']
const SOLID_INKS = ['#000000', '#ff0000', '#ffcc00', '#00aa00', '#0000ff']

// The look, picked once a render in get(), at either size (`sm`: small). The
// memo()'d pieces also take `hc` and `sm`, so a change of either draws them again.
const THEMES = {
  color: (a, sm) => ({
    page: 'bg-[#0b1020] text-white',
    header: 'bg-black/30 border-b border-white/10',
    clock: `text-${a}-200`,
    mark: ['#ffffff', '#1c7c66', '#8baa3a', '#c8a247'],
    tabs: 'bg-black/40 border-t border-white/10',
    tabOn: `text-${a}-300 bg-white/5`,
    tabOff: 'text-slate-400 active:bg-white/10',
    badge: () => `bg-${a}-500 text-white`,
    card: 'bg-white/5 border border-white/10',
    cardP: sm ? 'p-3' : 'p-4',
    cardPx: sm ? 'px-2' : 'px-3',
    toggleOn: `${sm ? 'p-2' : 'p-3'} bg-${a}-500 text-white`,
    toggleOff: `${sm ? 'p-2' : 'p-3'} bg-white/5 border border-white/10 text-slate-300 active:bg-white/10`,
    pillOn: 'px-1 justify-end bg-black/25',
    pillOff: 'px-1 justify-start bg-white/15',
    knob: 'bg-white',
    stateOn: 'text-white/80',
    stateOff: 'text-slate-500',
    label: 'text-slate-300',
    muted: 'text-slate-400',
    faint: 'text-slate-500',
    value: `text-${a}-300`,
    slider: `${sm ? 'h-7' : 'h-9'} bg-white/10`,
    sliderFill: `${sm ? 'h-7' : 'h-9'} bg-gradient-to-r from-${a}-700 to-${a}-400`,
    sliderLess: 0, // taken off the slider's width for its fill
    sliderMin: sm ? 28 : 36,
    minus: `bg-white/10 active:bg-${a}-700`,
    plus: `bg-${a}-500 active:bg-${a}-700`,
    swatchOn: 'border-4 border-white',
    swatchOff: 'active:border-2 active:border-white/60',
    paper: '#f1f5f9',
    paperBox: 'p-[8px]',
    inks: INKS,
    inkOn: 'border-4 border-white',
    inkOff: 'border-2 border-white/20',
    brushOn: 'bg-white/20',
    brushOff: 'active:bg-white/10',
    brushDot: () => 'bg-white',
    undo: 'px-3 bg-white/10 active:bg-white/20',
    undoOff: 'px-3 bg-white/10 active:bg-white/20',
    undoText: (can) => (can ? '' : 'text-white/40'),
    primary: `bg-${a}-600 active:bg-${a}-800`,
    primaryNote: 'text-white/70',
    cellOn: `bg-${a}-400 active:bg-${a}-600`,
    cellOff: 'bg-white/10 active:bg-white/25',
    solved: 'bg-black/70',
    solvedTitle: `text-${a}-300`,
    solvedNote: 'text-slate-300',
    chip: 'px-3 bg-white/10',
    chipText: `text-${a}-300`,
    stage: 'bg-slate-950 border border-white/10',
    wave: '#334155',
    spinTrack: '#1e293b',
    spinTrackW: 6,
    spin: '#e2e8f0',
    balls: BALL_COLORS,
    pad: `bg-slate-900 border-2 border-white/10 hover:border-${a}-400`,
    events: EVENT_COLORS,
    fade: true,
    tally: 'py-1 bg-white/5',
    tallyNumber: (type) => `text-[${EVENT_COLORS[type]}]`,
    demoActive: `bg-white/10 active:bg-${a}-600`,
    demoHover: 'border-2 border-white/10 hover:border-white hover:bg-white/5',
    demoGroup: 'bg-white/5',
    groupDot: `bg-slate-600 group-hover:bg-${a}-400`,
    groupText: 'text-slate-400 group-hover:text-white',
  }),
  high: (a, sm, color) => ({
    page: 'bg-white text-black',
    header: 'bg-white border-b-2 border-black',
    clock: 'text-black',
    mark: ['#000000', '#000000', '#000000', '#000000'],
    tabs: 'bg-white border-t-2 border-black',
    tabOn: 'bg-black text-white',
    tabOff: 'text-black',
    badge: (active) => (active ? 'bg-white text-black' : 'bg-black text-white'),
    card: 'bg-white border-2 border-black',
    cardP: sm ? 'p-[11px]' : 'p-[15px]',
    cardPx: sm ? 'px-[7px]' : 'px-[11px]',
    toggleOn: `${sm ? 'p-2' : 'p-3'} bg-black text-white`,
    toggleOff: `${sm ? 'p-[6px]' : 'p-[10px]'} bg-white border-2 border-black text-black`,
    pillOn: 'px-1 justify-end bg-white',
    pillOff: 'px-[2px] justify-start bg-white border-2 border-black',
    knob: 'bg-black',
    stateOn: 'text-white',
    stateOff: 'text-black',
    label: 'text-black',
    muted: 'text-black',
    faint: 'text-black',
    value: 'text-black',
    slider: `${sm ? 'h-7' : 'h-9'} bg-white border-2 border-black`,
    sliderFill: `${sm ? 'h-6' : 'h-8'} bg-black`,
    sliderLess: 6, // its border, and the 2 px the color fill runs over
    sliderMin: sm ? 24 : 32,
    minus: 'bg-white border-2 border-black text-black',
    plus: 'bg-black text-white',
    swatchOn: 'border-4 border-black',
    swatchOff: '',
    paper: '#ffffff',
    paperBox: 'p-[6px] border-2 border-black',
    inks: color ? SOLID_INKS : GREY_INKS,
    inkOn: 'border-2 border-black flex items-center justify-center',
    inkOff: 'border-2 border-black',
    brushOn: 'bg-black',
    brushOff: '',
    brushDot: (chosen) => (chosen ? 'bg-white' : 'bg-black'),
    undo: 'px-[10px] bg-white border-2 border-black',
    undoOff: 'px-3 bg-white',
    undoText: () => '',
    primary: 'bg-black text-white',
    primaryNote: 'text-white',
    cellOn: 'bg-black',
    cellOff: 'bg-white border-2 border-black',
    solved: 'bg-white border-2 border-black',
    solvedTitle: 'text-black',
    solvedNote: 'text-black',
    chip: 'px-[10px] bg-white border-2 border-black',
    chipText: 'text-black',
    stage: 'bg-white border-2 border-black',
    wave: '#000000',
    spinTrack: '#000000',
    spinTrackW: 2,
    spin: '#000000',
    balls: ['#000000'],
    pad: 'bg-white border-2 border-black',
    events: { tap: '#000000', doubleTap: '#000000', longPress: '#000000', pointerDown: '#000000', pointerUp: '#000000', pointerMove: '#000000' },
    fade: false,
    tally: 'py-[2px] bg-white border-2 border-black',
    tallyNumber: () => 'text-black',
    demoActive: 'bg-white border-2 border-black active:bg-black active:text-white',
    demoHover: 'border-2 border-black hover:bg-black hover:text-white',
    demoGroup: 'border-2 border-black',
    groupDot: 'bg-white border-2 border-black group-hover:bg-black',
    groupText: 'text-black group-hover:underline',
  }),
}
let T = THEMES.color('sky', false)
let lookOf = 'sky' // the accent T was made for, or 'high', and ':sm' when small

const DEFAULTS = {
  tab: 'controls', accent: 'sky',
  toggles: [true, false, true], level: 60, count: 3,
  strokes: [], based: 0, ink: 1, brush: 1,
  board: null, moves: 0,
  balls: null,
  events: [], counts: { tap: 0, doubleTap: 0, longPress: 0, pointerDown: 0, pointerUp: 0, pointerMove: 0 },
}
let S = null
const load = () => {
  if (S === null) S = Object.assign({}, DEFAULTS, frameos.recall('sink') ?? {})
  if (!S.board) newGame()
  if (!S.balls) S.balls = [newBall(120, 90, 0), newBall(300, 200, 1)]
}
const save = () => { S.rev = (S.rev ?? 0) + 1; frameos.remember('sink', S) }
const set = (patch) => { Object.assign(S, patch); save() }

// ---------------------------------------------------------------- pieces

const Icon = ({ d, className }) => (
  <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2}
    strokeLinecap="round" strokeLinejoin="round"><path d={d} /></svg>
)

const Mark = ({ sm }) => (
  <svg className={sm ? 'w-5 h-6' : 'w-6 h-7'} viewBox="0 0 24 28">
    <path d="M1.5 14V1.5h21" fill="none" stroke={T.mark[0]} strokeWidth={3} strokeLinecap="round" />
    <path d="M22.5 16v10.5H12" fill="none" stroke={T.mark[0]} strokeWidth={3} strokeLinecap="round" />
    <rect x={4} y={18} width={6} height={6} rx={1.2} fill={T.mark[1]} />
    <rect x={10} y={12} width={6} height={6} rx={1.2} fill={T.mark[2]} />
    <rect x={16} y={6} width={6} height={6} rx={1.2} fill={T.mark[3]} />
  </svg>
)

// A tab's label shows where the tab is 60 px wide or more.
const Tab = memo(({ id, label, d, active, accent, badge, hc, sm }) => (
  <div className={`flex-1 flex flex-col items-center justify-center gap-1 ${active ? T.tabOn : T.tabOff}`}
    onClick={() => set({ tab: id })}>
    <Icon d={d} className={sm ? 'w-5 h-5' : 'w-6 h-6'} />
    {label ? <span className="text-xs font-semibold">{label}</span> : null}
    {badge > 0 ? (
      <div className={`absolute ${sm ? 'top-0 right-1 h-4 px-1' : 'top-1 right-3 h-5 px-2'} flex items-center justify-center rounded-full ${T.badge(active)}`}>
        <span className={`${sm ? 'text-[10px]' : 'text-xs'} font-bold`}>{`${badge > 99 ? '99+' : badge}`}</span>
      </div>
    ) : null}
  </div>
))

const Card = ({ className, children }) => (
  <div className={`rounded-2xl ${T.card} ${className ?? ''}`}>{children}</div>
)

// -------------------------------------------------------------- controls

const TOGGLES = [
  ['Lights', 'M9 18h6M10 22h4M12 2a7 7 0 0 0-4 12.7V17h8v-2.3A7 7 0 0 0 12 2z'],
  ['Music', 'M9 18V5l12-2v13M6 15a3 3 0 1 0 0 6 3 3 0 0 0 0-6zM18 13a3 3 0 1 0 0 6 3 3 0 0 0 0-6z'],
  ['Turbo', 'M13 2L3 14h9l-1 8 10-12h-9z'],
]

const Toggle = memo(({ i, on, accent, hc, sm }) => (
  <div className={`flex flex-col justify-between ${sm ? 'rounded-xl' : 'rounded-2xl'} ${on ? T.toggleOn : T.toggleOff}`}
    onClick={() => { S.toggles[i] = !S.toggles[i]; save() }}>
    <div className="flex items-center justify-between">
      <Icon d={TOGGLES[i][1]} className={sm ? 'w-5 h-5' : 'w-7 h-7'} />
      <div className={`flex items-center ${sm ? 'w-8 h-5' : 'w-11 h-6'} rounded-full ${on ? T.pillOn : T.pillOff}`}>
        <div className={`${sm ? 'w-3 h-3' : 'w-4 h-4'} rounded-full ${T.knob}`} />
      </div>
    </div>
    <div className="flex flex-col">
      <span className={`${sm ? 'text-sm' : 'text-base'} font-semibold`}>{TOGGLES[i][0]}</span>
      <span className={`text-xs ${on ? T.stateOn : T.stateOff}`}>{on ? 'On' : 'Off'}</span>
    </div>
  </div>
))

// In high contrast the accents are not drawn in their colors (greys a panel
// cannot tell apart): each is its initial, the one picked filled.
const Swatch = memo(({ color, chosen, hc, sm }) => hc ? (
  <div className={`flex items-center justify-center ${sm ? 'w-7 h-7' : 'w-9 h-9'} rounded-full border-2 border-black ${chosen ? 'bg-black text-white' : 'bg-white text-black'}`}
    onClick={() => set({ accent: color })}>
    <span className={`${sm ? 'text-sm' : 'text-base'} font-bold`}>{color[0].toUpperCase()}</span>
  </div>
) : (
  <div className={`${sm ? 'w-7 h-7' : 'w-9 h-9'} rounded-full bg-${color}-500 ${chosen ? T.swatchOn : T.swatchOff}`}
    onClick={() => set({ accent: color })} />
))

const Controls = ({ accent, hc }) => {
  const level = S.level
  const sm = small
  // e.width: the slider's own (2026.10.22+); sliderW on an older frame.
  const setLevel = (e) => set({ level: Math.max(0, Math.min(100, Math.round((e.localX / (e.width ?? sliderW)) * 100))) })
  // The keys (a frame's buttons, Tab and Enter) press it too: each press is ten
  // more, and past 100 it starts again at 0. A finger's tap set it already.
  const stepLevel = (e) => { if (e?.key) set({ level: S.level >= 100 ? 0 : Math.min(100, Math.floor(S.level / 10) * 10 + 10) }) }
  const row = sm ? 'h-16' : `h-[${ctrlRow}px]`
  // A small page keeps every control on its first screen where it can (fit()
  // decides, and sizes the slider): the brightness on one row (its name, the
  // slider, the value), and on a short strip (a 5.79" e-paper) the controls in
  // two columns. The stepper and the accent side by side, or one under the
  // other where the page is narrow.
  const wideShort = sm && controlColumns
  const inline = sm && brightnessRow
  const stack = compact && !wideShort && pageW < 360
  const slider = (
    <div className={`${inline ? 'flex-1 ' : ''}rounded-full ${T.slider}`} onPointerDown={setLevel} onPointerMove={(e) => { if (e.buttons) setLevel(e) }} onClick={stepLevel}>
      <div className={`rounded-full ${T.sliderFill} w-[${Math.round(Math.max(T.sliderMin, (level / 100) * (sliderW - T.sliderLess)))}px] flex items-center justify-end px-1`}>
        <div className={`${sm ? 'w-5 h-5' : 'w-7 h-7'} rounded-full bg-white`} />
      </div>
    </div>
  )
  const toggles = (
    <div className={`grid grid-cols-3 ${sm ? 'gap-2 h-[72px]' : `gap-3 h-[${ctrlRow}px]`}`}>
      {S.toggles.map((on, i) => <Toggle i={i} on={on} accent={accent} hc={hc} sm={sm} />)}
    </div>
  )
  const brightness = inline ? (
    <Card className={`flex items-center gap-2 ${T.cardP}`}>
      <span className={`w-[${BRIGHTNESS_LABEL_W}px] shrink-0 text-xs uppercase font-semibold ${T.label}`}>Brightness</span>
      {slider}
      <span className={`w-[${BRIGHTNESS_VALUE_W}px] shrink-0 text-right text-base font-bold ${T.value}`}>{`${level}%`}</span>
    </Card>
  ) : (
    <Card className={`flex flex-col gap-2 ${T.cardP}`}>
      <div className="flex items-center justify-between">
        <span className={`${sm ? 'text-xs' : 'text-sm'} uppercase font-semibold ${T.label}`}>Brightness</span>
        <span className={`${sm ? 'text-base' : 'text-lg'} font-bold ${T.value}`}>{`${level}%`}</span>
      </div>
      {slider}
    </Card>
  )
  const counter = (
    <Card className={`flex-1 flex items-center justify-between ${T.cardPx}${stack || wideShort ? ` ${row}` : ''}`}>
      <div className={`flex items-center justify-center ${sm ? 'w-9 h-9' : 'w-11 h-11'} rounded-full ${T.minus}`}
        onClick={() => set({ count: S.count - 1 })}>
        <Icon d="M5 12h14" className={sm ? 'w-5 h-5' : 'w-6 h-6'} />
      </div>
      <div className="flex flex-col items-center" onDoubleClick={() => set({ count: 0 })}>
        <span className={`${sm ? 'text-3xl' : 'text-4xl'} font-bold`}>{`${S.count}`}</span>
        <span className={`text-xs ${T.faint}`}>double-tap: 0</span>
      </div>
      <div className={`flex items-center justify-center ${sm ? 'w-9 h-9' : 'w-11 h-11'} rounded-full ${T.plus}`}
        onClick={() => set({ count: S.count + 1 })} onLongPress={() => set({ count: S.count + 10 })}>
        <Icon d="M12 5v14M5 12h14" className={sm ? 'w-5 h-5' : 'w-6 h-6'} />
      </div>
    </Card>
  )
  const accents = (
    <Card className={`flex-1 flex flex-col justify-center gap-2 ${T.cardPx}${stack || wideShort ? ` ${row}` : ''}`}>
      <span className={`text-xs uppercase font-semibold ${T.muted}`}>Accent</span>
      <div className="flex justify-between">
        {ACCENTS.map((c) => <Swatch color={c} chosen={c === accent} hc={hc} sm={sm} />)}
      </div>
    </Card>
  )
  if (wideShort)
    return (
      <div className="flex gap-2">
        <div className="flex-1 min-w-0 flex flex-col gap-2">
          {toggles}
          {brightness}
        </div>
        <div className="flex-1 min-w-0 flex flex-col gap-2">
          {counter}
          {accents}
        </div>
      </div>
    )
  return (
    <div className={`flex flex-col ${sm ? 'gap-2' : 'gap-3'}`}>
      {toggles}
      {brightness}
      <div className={stack ? `flex flex-col ${sm ? 'gap-2' : 'gap-3'}` : `flex ${sm ? 'gap-2' : 'gap-3'} ${row}`}>
        {counter}
        {accents}
      </div>
    </div>
  )
}

// ----------------------------------------------------------------- paint

const Ink = memo(({ i, chosen, hc }) => (
  <div className={`w-7 h-7 shrink-0 rounded-full bg-[${T.inks[i]}] ${chosen ? T.inkOn : T.inkOff}`}
    onClick={() => set({ ink: i })}>
    {hc && chosen ? <div className="w-3 h-3 rounded-full bg-white border-2 border-black" /> : null}
  </div>
))

const Brush = memo(({ i, chosen, hc }) => (
  <div className={`flex items-center justify-center w-7 h-7 shrink-0 rounded-lg ${chosen ? T.brushOn : T.brushOff}`}
    onClick={() => set({ brush: i })}>
    <div className={`rounded-full ${T.brushDot(chosen)} ${['w-1 h-1', 'w-2 h-2', 'w-4 h-4'][i]}`} />
  </div>
))

// Paint draws into a canvas (frameos.canvas): a stroke is lines from the
// last point to the next as the finger moves (the positions a move that
// waited stood for included, e.points), drawn once, and a frame repaints
// only those. S.strokes is the record, [ink, brush, x0, y0, x1, y1,
// ...] each, for Undo and for a canvas made afresh (a new interpreter); it
// is drawn again only then, never per render. All but the last UNDO strokes
// are also in `base` (S.based of them), a second canvas Undo starts from, so
// an Undo copies it and draws a few strokes, not the whole record (seconds
// on an ESP32 once the record is full). The paper and the inks are the
// look's: a change of Contrast draws the record again.
const INSET = 8
let canvasW = pageW - 2 * INSET, canvasH = paintH - 2 * INSET // the paper less its inset
const MAX_POINTS = 3000 // x, y pairs kept for a fresh canvas; the oldest strokes go past it
const UNDO = 12 // strokes Undo can take back
let canvas = null
let base = null
let drawing = null // the stroke the finger is drawing, while it is down

const strokeSvg = ([ink, brush, ...pts]) => pts.length === 2
  ? <circle cx={pts[0]} cy={pts[1]} r={BRUSHES[brush]} fill={T.inks[ink]} />
  : <polyline points={pts.join(' ')} fill="none" stroke={T.inks[ink]} strokeWidth={BRUSHES[brush] * 2}
      strokeLinecap="round" strokeLinejoin="round" />
// The canvas again: `base`, then the strokes it does not hold.
const redraw = () => {
  frameos.draw(canvas, <image href={base} x={0} y={0} width={canvasW} height={canvasH} preserveAspectRatio="none" />)
  for (const stroke of S.strokes.slice(S.based)) frameos.draw(canvas, strokeSvg(stroke))
}
// A finished stroke into the record; the oldest past UNDO go into `base`.
const keep = (stroke) => {
  S.strokes.push(stroke)
  while (S.strokes.length - S.based > UNDO) frameos.draw(base, strokeSvg(S.strokes[S.based++]))
  let points = S.strokes.reduce((n, s) => n + (s.length - 2) / 2, 0)
  while (points > MAX_POINTS && S.strokes.length > 1) {
    if (S.based === 0) frameos.draw(base, strokeSvg(S.strokes[S.based++]))
    points -= (S.strokes.shift().length - 2) / 2
    S.based--
  }
  save()
}
const paintAt = (e) => [Math.round(e.localX), Math.round(e.localY)]

const Paint = ({ accent, hc }) => {
  const canUndo = S.strokes.length > S.based
  return (
    <div className={`flex flex-col ${small ? 'gap-2' : 'gap-3'}`}>
      <div className={`w-[${pageW}px] h-[${paintH}px] rounded-2xl bg-[${T.paper}] ${T.paperBox}`}>
        <img className={`w-[${canvasW}px] h-[${canvasH}px]`} src={canvas}
          onPointerDown={(e) => {
            const [x, y] = paintAt(e)
            drawing = [S.ink, S.brush, x, y]
            frameos.draw(canvas, strokeSvg(drawing))
          }}
          onPointerMove={(e) => {
            if (!drawing) return false
            // The positions a move that waited for a busy frame stood for
            // (e.points, oldest first), then its own: every one joins the
            // stroke, so a slow panel draws the same line a fast one does.
            const passed = Array.isArray(e.points) ? e.points : []
            const at = []
            for (let i = 0; i + 1 < passed.length; i += 2) at.push(Math.round(passed[i]), Math.round(passed[i + 1]))
            at.push(...paintAt(e))
            let [lx, ly] = drawing.slice(-2)
            const line = [lx, ly]
            for (let i = 0; i + 1 < at.length; i += 2) {
              if (Math.abs(at[i] - lx) + Math.abs(at[i + 1] - ly) < 2) continue
              lx = at[i]
              ly = at[i + 1]
              line.push(lx, ly)
              drawing.push(lx, ly)
            }
            if (line.length < 4) return false // nothing a finger can see: no render
            frameos.draw(canvas, <polyline points={line.join(' ')} fill="none" stroke={T.inks[drawing[0]]}
              strokeWidth={BRUSHES[drawing[1]] * 2} strokeLinecap="round" strokeLinejoin="round" />)
          }}
          onPointerUp={() => {
            if (!drawing) return
            keep(drawing)
            drawing = null
          }} />
        {S.strokes.length === 0 && !drawing ? (
          <div className="absolute inset-0 flex items-center justify-center">
            <span className={`${small ? 'text-sm' : 'text-lg'} ${T.muted}`}>Tap or drag to paint</span>
          </div>
        ) : null}
      </div>
      <div className={compact ? 'flex flex-wrap items-center justify-between gap-y-2' : 'flex items-center justify-between h-12'}>
        <div className="flex items-center gap-[6px] shrink-0">
          {INKS.map((_, i) => <Ink i={i} chosen={i === S.ink} hc={hc} />)}
        </div>
        <div className="flex items-center gap-1 shrink-0">
          {BRUSHES.map((_, i) => <Brush i={i} chosen={i === S.brush} hc={hc} />)}
        </div>
        <div className="flex items-center gap-2 shrink-0">
          <div className={`flex items-center justify-center h-9 rounded-lg ${canUndo ? T.undo : T.undoOff}`}
            onClick={() => { if (S.strokes.length > S.based) { S.strokes.pop(); redraw(); save() } }}>
            <span className={`text-sm font-semibold whitespace-nowrap ${T.undoText(canUndo)}`}>Undo</span>
          </div>
          <div className={`flex flex-col items-center justify-center h-11 px-3 rounded-lg ${T.primary}`}
            onLongPress={() => { frameos.clear(canvas, T.paper); frameos.clear(base, T.paper); set({ strokes: [], based: 0 }) }}>
            <span className="text-sm font-semibold whitespace-nowrap">Clear</span>
            <span className={`text-xs whitespace-nowrap ${T.primaryNote}`}>hold 1 s</span>
          </div>
        </div>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------- lights

const N = 5
const flip = (board, i) => {
  const x = i % N, y = Math.floor(i / N)
  for (const [dx, dy] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) {
    const nx = x + dx, ny = y + dy
    if (nx >= 0 && nx < N && ny >= 0 && ny < N) board[ny * N + nx] = !board[ny * N + nx]
  }
}
function newGame() {
  const board = new Array(N * N).fill(false)
  // Pressed from solved, so it can be solved: as many presses undo it.
  while (!board.some(Boolean)) {
    for (let k = 0; k < 9; k++) flip(board, Math.floor(Math.random() * N * N))
  }
  S.board = board
  S.moves = 0
  save()
}

const Cell = memo(({ i, on, accent, hc }) => (
  <div className={`w-[${cellW}px] h-[${cellW}px] rounded-xl ${on ? T.cellOn : T.cellOff}`}
    onClick={() => { flip(S.board, i); S.moves++; save() }} />
))

const Lights = ({ accent, hc }) => {
  const lit = S.board.filter(Boolean).length
  const solved = lit === 0
  return (
    <div className={`flex flex-col ${small ? 'gap-2' : 'gap-3'} items-center`}>
      <div className="flex items-center justify-between w-full h-10">
        <div className="flex flex-col">
          <span className={`${small ? 'text-base' : 'text-lg'} font-bold`}>Lights Out</span>
          <span className={`text-xs ${T.muted}`}>{`${lit} lit, ${S.moves} moves`}</span>
        </div>
        <div className={`flex items-center ${small ? 'h-8 px-3' : 'h-9 px-4'} rounded-full ${T.primary}`}
          onClick={() => newGame()}>
          <span className="text-sm font-semibold">New game</span>
        </div>
      </div>
      <div className={`w-[${boardW}px]`}>
        <div className="grid grid-cols-5 gap-[6px]">
          {S.board.map((on, i) => <Cell i={i} on={on} accent={accent} hc={hc} />)}
        </div>
        {solved ? (
          <div className={`absolute inset-0 flex flex-col items-center justify-center gap-1 rounded-2xl ${T.solved}`}>
            <span className={`text-3xl font-bold ${T.solvedTitle}`}>Solved!</span>
            <span className={`text-sm ${T.solvedNote}`}>{`in ${S.moves} moves`}</span>
          </div>
        ) : null}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------- motion

function newBall(x, y, n) {
  const angle = (n * 2.39996) % (Math.PI * 2)
  const speed = 140 + (n % 3) * 40
  return { x, y, vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed, t0: Date.now(), r: 14 + (n % 3) * 4, c: n % BALL_COLORS.length }
}
// Where a point moving at `v` px/s from `p` is after `t` s between 0 and `span`.
const bounce = (p, v, t, span) => {
  const d = (((p + v * t) % (2 * span)) + 2 * span) % (2 * span)
  return d > span ? 2 * span - d : d
}
const frames = []

const Motion = ({ accent, now }) => {
  const fps = frames.length
  const spin = ((now % 1200) / 1200) * 360
  const wave = []
  for (let x = 0; x <= pageW; x += 16) {
    wave.push(`${x === 0 ? 'M' : 'L'}${x} ${(motionH - 40 + Math.sin(x / 40 + now / 300) * 14).toFixed(1)}`)
  }
  return (
    <div className={`flex flex-col ${small ? 'gap-2' : 'gap-3'}`}>
      <div className={`flex items-center justify-between ${small ? 'gap-2 min-h-8' : 'h-8'}`}>
        <span className={`${small ? 'flex-1 text-xs leading-tight' : 'text-sm'} ${T.muted}`}>{`${S.balls.length} balls. Tap to add one, hold to reset.`}</span>
        <div className={`flex items-center shrink-0 h-7 rounded-full ${T.chip}`}>
          <span className={`text-sm font-bold ${T.chipText}`}>{`${fps} fps`}</span>
        </div>
      </div>
      <div className={`w-[${pageW}px] h-[${motionH}px] rounded-2xl ${T.stage}`}
        onPointerDown={(e) => {
          if (S.balls.length < 12) S.balls.push(newBall(Math.round(e.localX), Math.round(e.localY), S.balls.length))
          save()
        }}
        onLongPress={() => set({ balls: [newBall(120, 90, 0)] })}>
        <svg className="w-full h-full" viewBox={`0 0 ${pageW} ${motionH}`}>
          <path d={wave.join(' ')} fill="none" stroke={T.wave} strokeWidth={3} strokeLinecap="round" />
          <g transform={`translate(${pageW - 44} 44) rotate(${spin.toFixed(1)})`}>
            <circle cx={0} cy={0} r={22} fill="none" stroke={T.spinTrack} strokeWidth={T.spinTrackW} />
            <path d="M0 -22 A22 22 0 0 1 22 0" fill="none" stroke={T.spin} strokeWidth={6} strokeLinecap="round" />
          </g>
          {S.balls.map((b) => {
            const t = (now - b.t0) / 1000
            const x = b.r + bounce(b.x - b.r, b.vx, t, pageW - 2 * b.r)
            const y = b.r + bounce(b.y - b.r, b.vy, t, motionH - 2 * b.r)
            return <circle cx={x.toFixed(1)} cy={y.toFixed(1)} r={b.r} fill={T.balls[b.c % T.balls.length]} />
          })}
        </svg>
      </div>
    </div>
  )
}

// ----------------------------------------------------------------- touch

const Touch = ({ accent, hc }) => {
  const log = (e) => {
    S.events.push([e.type, Math.round(e.localX), Math.round(e.localY)])
    if (S.events.length > 12) S.events.shift()
    S.counts[e.type] = (S.counts[e.type] ?? 0) + 1
    save()
  }
  const last = S.events[S.events.length - 1]
  const column = small && pageW < 420 // the three demos one under another
  return (
    <div className={`flex flex-col ${small ? 'gap-2' : 'gap-3'}`}>
      <div className={`w-[${pageW}px] h-[${padH}px] rounded-2xl ${T.pad}`}
        onClick={log} onDoubleClick={log} onLongPress={log} onPointerDown={log} onPointerUp={log} onPointerMove={log}>
        <svg className="w-full h-full" viewBox={`0 0 ${pageW} ${padH}`}>
          {S.events.map(([type, x, y], i) => {
            const fade = T.fade ? (i + 1) / S.events.length : 1
            const r = { tap: 16, doubleTap: 26, longPress: 36, pointerDown: 5, pointerUp: 10, pointerMove: 3 }[type] ?? 8
            const fill = type === 'pointerDown' || (T.fade && type === 'longPress') || type === 'pointerMove'
            return <circle cx={x} cy={y} r={r} fill={fill ? T.events[type] : 'none'}
              fillOpacity={type === 'longPress' ? 0.35 * fade : fade}
              stroke={T.events[type]} strokeWidth={fill ? 0 : 3} strokeOpacity={fade} />
          })}
        </svg>
        <div className="absolute inset-x-0 bottom-2 flex justify-center">
          <span className={`text-sm ${T.muted}`}>
            {last ? `${last[0]} at ${last[1]}, ${last[2]}` : 'Tap, hold, drag'}
          </span>
        </div>
      </div>
      <div className={`flex ${small ? 'gap-1' : 'gap-2'}`}>
        {Object.keys(EVENT_COLORS).map((type) => (
          <div className={`flex-1 min-w-0 flex flex-col items-center rounded-xl ${T.tally}`}>
            <span className={`${small ? 'text-base' : 'text-lg'} font-bold ${T.tallyNumber(type)}`}>{`${S.counts[type] ?? 0}`}</span>
            <span className={`${small ? 'text-[10px]' : 'text-xs'} truncate ${T.muted}`}>{type}</span>
          </div>
        ))}
      </div>
      <div className={column ? 'flex flex-col gap-2' : 'flex gap-2 h-12'}>
        <div className={`flex-1 ${column ? 'min-h-10' : ''} flex items-center justify-center rounded-xl ${T.demoActive}`}>
          <span className="text-sm font-semibold">active:</span>
        </div>
        <div className={`flex-1 ${column ? 'min-h-10' : ''} flex items-center justify-center rounded-xl ${T.demoHover}`}>
          <span className="text-sm font-semibold">hover:</span>
        </div>
        <div className={`group flex-1 ${column ? 'min-h-10' : ''} flex items-center justify-center gap-2 rounded-xl ${T.demoGroup}`}>
          <div className={`w-3 h-3 rounded-full ${T.groupDot}`} />
          <span className={`text-sm font-semibold ${T.groupText}`}>group-hover:</span>
        </div>
      </div>
    </div>
  )
}

// ------------------------------------------------------------------ page

const PAGES = { controls: Controls, paint: Paint, lights: Lights, touch: Touch }
const two = (n) => String(n).padStart(2, '0')

// A page that only changes when the state does (`rev`), the look (`hc`) or the
// size the UI is laid out at (`box`).
const Page = memo(({ tab, accent, rev, hc, box }) => {
  const Body = PAGES[tab] ?? Controls
  return <Body accent={accent} hc={hc} />
})

const Title = memo(({ hc, sm }) => (
  <div className="flex items-center gap-2">
    <Mark sm={sm} />
    <span className={`${sm ? 'text-base' : 'text-lg'} font-bold`}>Kitchen sink</span>
  </div>
))

// The size the UI is laid out at: the image it draws into, else the frame
// as the scene sees it (app.frame is the panel's, before the turn).
const uiSize = (app, context) => {
  const turned = [90, 270].includes(app.frame.rotate)
  return [context?.imageWidth ?? (turned ? app.frame.height : app.frame.width),
    context?.imageHeight ?? (turned ? app.frame.width : app.frame.height)]
}

// The header, the tab bar, the page's padding and its gaps, at either size.
// What a small page does not fit, it scrolls to.
const CHROME = { normal: { header: 48, tabs: 64, pad: 16, gap: 12 }, small: { header: 36, tabs: 44, pad: 8, gap: 8 } }
const BRIGHTNESS_LABEL_W = 84
const BRIGHTNESS_VALUE_W = 44
let controlColumns = false
let brightnessRow = false
const fit = ([w, h]) => {
  if (!small) {
    pageW = w - 32; sliderW = pageW - 32; paintH = h - 204; motionH = h - 188; padH = h - 272
    boardW = Math.min(pageW, h - 196)
    // The controls take 480 px with the header and the tab bar. A tall page
    // (a portrait e-paper, a square 720) gives their two rows of cards what it
    // has left, up to twice their height; a little less (a layout's bar above
    // the scene) takes it from them.
    const spare = h - 480
    ctrlRow = 96 + (spare > 40 ? Math.min(96, Math.floor(spare * 0.4)) : spare < 0 ? Math.max(-24, Math.floor(spare / 2)) : 0)
  } else {
    const c = CHROME.small
    const room = h - c.header - c.tabs - 2 * c.pad - c.gap // under a page's first row
    pageW = w - 2 * c.pad
    // The controls in two columns on a short strip; the brightness's name,
    // slider and value on one row where the page is 300 px or more across.
    controlColumns = pageW >= 560
    brightnessRow = pageW >= 300
    const column = controlColumns ? Math.floor((pageW - 8) / 2) : pageW
    sliderW = column - 24 - (brightnessRow ? BRIGHTNESS_LABEL_W + BRIGHTNESS_VALUE_W + 16 : 0)
    // The colors, the brushes and Undo and Clear: one row, two or three.
    paintH = Math.max(120, room - (pageW >= 410 ? 48 : pageW >= 260 ? 88 : 124))
    motionH = Math.max(120, room - 32)
    padH = Math.max(100, room - (pageW < 420 ? 190 : 102))
    boardW = Math.min(pageW, Math.max(160, room - 40))
  }
  cellW = Math.floor((boardW - 24) / 5) // five cells, four 6 px gaps
  canvasW = pageW - 2 * INSET; canvasH = paintH - 2 * INSET
}

// On a round panel (only the circle inside the square shows) the UI is laid
// out in the square inside that circle, 12 px in from the rim.
// There, and on a small screen, the page scrolls (`compact`), and where it is
// narrow the controls' last row is a column. Small: under 380 px across or
// 340 px down, where the sizes made for 480 px do not fit.
let compact = false
let small = false
const roundSide = (context) => {
  if (context?.round !== true) return 0
  return Math.floor((Math.min(context.imageWidth, context.imageHeight) / 2 - 12) * Math.SQRT2)
}

export function get(app, context) {
  const side = roundSide(context)
  const [w, h] = side ? [side, side] : uiSize(app, context)
  small = w < 380 || h < 340
  // Shorter than the 480 px the pages are made for: what does not fit scrolls.
  compact = side > 0 || small || h < 456
  const ui = getUi(app, context, side)
  if (!side) return ui
  const W = context.imageWidth, H = context.imageHeight
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${T.page}`}>
      <div className={`absolute left-[${(W - side) >> 1}px] top-[${(H - side) >> 1}px] w-[${side}px] h-[${side}px]`}>{ui}</div>
    </div>
  )
}

function getUi(app, context, side) {
  const box = side ? [side, side] : uiSize(app, context)
  fit(box)
  load()
  const accent = S.accent
  const hc = highContrast(app)
  const sm = small
  const inkColor = app.frame.color !== false
  const look = (hc ? (inkColor ? 'high-ink' : 'high') : accent) + (sm ? ':sm' : '')
  if (look !== lookOf) { T = hc ? THEMES.high(accent, sm, inkColor) : THEMES.color(accent, sm); lookOf = look }
  if (S.tab === 'paint') {
    // The same canvases every render; made afresh (a new interpreter), they get the record again,
    // and so do they when the look changed (another paper, other inks).
    canvas = frameos.canvas('paint', canvasW, canvasH, T.paper)
    base = frameos.canvas('paint-base', canvasW, canvasH, T.paper)
    const relook = (frameos.recall('paper') ?? '#f1f5f9') !== T.paper
    if (relook) {
      frameos.remember('paper', T.paper)
      if (!base?.fresh) frameos.clear(base, T.paper)
    }
    if (base?.fresh || relook) for (const stroke of S.strokes.slice(0, S.based)) frameos.draw(base, strokeSvg(stroke))
    if (canvas?.fresh || base?.fresh || relook) redraw()
  }
  // `at` (a field) pins the time, for a snapshot; empty, it is the clock.
  const now = app.config.at ? new Date(app.config.at).getTime() : Date.now()
  frames.push(now)
  while (frames.length && now - frames[0] > 1000) frames.shift()
  // Off the motion page, one render a second, just after it turns.
  if (S.tab !== 'motion') frameos.setNextSleep(1.02 - (now % 1000) / 1000)
  const d = new Date(now)
  const events = Object.values(S.counts).reduce((a, b) => a + b, 0)
  return (
    <div className={`flex flex-col ${T.page}${compact ? ' w-full h-full' : ''}`}>
      <div className={`flex items-center justify-between ${sm ? 'h-9 px-3' : 'h-12 px-4'} ${T.header}`}>
        <Title hc={hc} sm={sm} />
        <span className={`${sm ? 'text-base' : 'text-lg'} font-mono ${T.clock}`}>{`${two(d.getHours())}:${two(d.getMinutes())}:${two(d.getSeconds())}`}</span>
      </div>
      <div className={`flex-1 ${sm ? 'p-2' : 'p-4'}${compact ? ' min-h-0 overflow-y-auto' : ''}`}>
        {S.tab === 'motion' ? <Motion accent={accent} now={now} /> : <Page tab={S.tab} accent={accent} rev={S.rev ?? 0} hc={hc} box={box.join('x')} />}
      </div>
      <div className={`flex ${sm ? 'h-11' : 'h-16'} ${T.tabs}`}>
        {TABS.map(([id, label, path]) => (
          <Tab id={id} label={box[0] / TABS.length >= 60 ? label : null} d={path} active={S.tab === id} accent={accent}
            badge={id === 'touch' ? events : 0} hc={hc} sm={sm} />
        ))}
      </div>
    </div>
  )
}
